import { Hono } from 'hono'
import { cors } from 'hono/cors'
import { renderAdminCmsPage, renderPmsMarketingSection, escHtml, formatMultiline } from './cms'

type Bindings = {
  DB: D1Database
}

const app = new Hono<{ Bindings: Bindings }>()

function hasAdminCookie(c: any): boolean {
  const cookieHeader = c.req.header('cookie') || ''
  return /(?:^|;\s*)admin_token=[^;\s]+/.test(cookieHeader)
}

// Embedded logo — served as data URL so it works in CF Workers runtime
const LOGO_DATA_URL = 'data:image/png;base64,'

app.use('/api/*', cors())

// ===== ADMIN AUTH GUARD =====
app.use('/admin/*', async (c, next) => {
  const p = c.req.path
  if (p === '/admin' || p === '/admin/' || p === '/admin/login' || p === '/admin/logout') {
    return next()
  }
  if (!hasAdminCookie(c)) {
    return c.redirect('/admin/login')
  }
  return next()
})

// ===== PERFORMANCE: Cache HTML pages for 60s at CDN edge =====
app.use('*', async (c, next) => {
  await next()
  const ct = c.res.headers.get('Content-Type') || ''
  const path = c.req.path
  // Cache public HTML pages at CDN for 60s, browser 30s
  if (ct.includes('text/html') && !path.startsWith('/admin') && !path.startsWith('/api')) {
    c.res.headers.set('Cache-Control', 'public, max-age=30, s-maxage=60, stale-while-revalidate=300')
  }
  // Add security headers (iframe-compatible)
  c.res.headers.set('X-Content-Type-Options', 'nosniff')
})

// ========== HELPER: get site settings ==========
async function getSiteSettings(db: D1Database): Promise<Record<string, string>> {
  try {
    const result = await db.prepare(`SELECT key, value FROM site_settings`).all()
    const settings: Record<string, string> = {}
    for (const row of (result.results || []) as any[]) {
      settings[row.key] = row.value || ''
    }
    return settings
  } catch {
    return {}
  }
}

// ========== HOME PAGE ==========
app.get('/', async (c) => {
  const db = c.env.DB
  let featuredProperties: any[] = []
  let recentProperties: any[] = []
  let settings: Record<string, string> = {}
  let ads: any[] = []
  let recentPosts: any[] = []

  try {
    const featuredResult = await db.prepare(
      `SELECT * FROM properties WHERE is_featured = 1 AND status = 'active' ORDER BY created_at DESC LIMIT 6`
    ).all()
    featuredProperties = (featuredResult.results || []) as any[]

    const recentResult = await db.prepare(
      `SELECT * FROM properties WHERE status = 'active' ORDER BY created_at DESC LIMIT 8`
    ).all()
    recentProperties = (recentResult.results || []) as any[]

    settings = await getSiteSettings(db)

    const adsResult = await db.prepare(
      `SELECT * FROM ads WHERE is_active = 1 AND position = 'banner_top' ORDER BY created_at DESC LIMIT 1`
    ).all()
    ads = adsResult.results || []

    try {
      const postsResult = await db.prepare(
        `SELECT id, title, slug, excerpt, cover_image, author, category, created_at FROM blog_posts WHERE status = 'published' ORDER BY created_at DESC LIMIT 3`
      ).all()
      recentPosts = postsResult.results || []
    } catch(e) {}
  } catch (e) {}

  return c.html(homePage(featuredProperties, recentProperties, settings, ads, recentPosts))
})

// ========== PROPERTIES LIST PAGE ==========
app.get('/properties', async (c) => {
  const db = c.env.DB
  const category = c.req.query('category') || ''
  const area = c.req.query('area') || ''
  const type = c.req.query('type') || ''
  const minPrice = c.req.query('min_price') || ''
  const maxPrice = c.req.query('max_price') || ''
  const beds = c.req.query('beds') || ''
  const search = c.req.query('q') || ''
  const page = parseInt(c.req.query('page') || '1')
  const limit = 12

  let where = `WHERE status = 'active'`
  let params: any[] = []

  if (category) { where += ` AND category = ?`; params.push(category) }
  if (area) { where += ` AND area LIKE ?`; params.push(`%${area}%`) }
  if (type) { where += ` AND property_type = ?`; params.push(type) }
  if (minPrice) { where += ` AND price >= ?`; params.push(parseFloat(minPrice)) }
  if (maxPrice) { where += ` AND price <= ?`; params.push(parseFloat(maxPrice)) }
  if (beds) { where += ` AND bedrooms >= ?`; params.push(parseInt(beds)) }
  if (search) { where += ` AND (title LIKE ? OR location LIKE ? OR area LIKE ?)`; params.push(`%${search}%`, `%${search}%`, `%${search}%`) }

  let properties: any[] = []
  let total = 0
  let sidebarAds: any[] = []

  try {
    const countResult = await db.prepare(`SELECT COUNT(*) as cnt FROM properties ${where}`).bind(...params).first() as any
    total = countResult?.cnt || 0

    const offset = (page - 1) * limit
    const result = await db.prepare(
      `SELECT * FROM properties ${where} ORDER BY is_featured DESC, created_at DESC LIMIT ? OFFSET ?`
    ).bind(...params, limit, offset).all()
    properties = result.results || []

    const adsResult = await db.prepare(`SELECT * FROM ads WHERE is_active = 1 AND position = 'sidebar' ORDER BY created_at DESC LIMIT 2`).all()
    sidebarAds = adsResult.results || []
  } catch (e) {}

  return c.html(propertiesPage(properties, total, page, limit, { category, area, type, minPrice, maxPrice, beds, search }, sidebarAds))
})

