// ========== SINGLE PROPERTY PAGE ==========
app.get('/property/:id', async (c) => {
  const db = c.env.DB
  const id = c.req.param('id')
  let property: any = null
  let similar: any[] = []
  let agent: any = null
  let videos: any[] = []
  let rooms: any[] = []
  let sidebarAds: any[] = []

  try {
    property = await db.prepare(`SELECT * FROM properties WHERE listing_id = ? OR id = ?`).bind(id, id).first()
    if (property) {
      await db.prepare(`UPDATE properties SET views = views + 1 WHERE id = ?`).bind(property.id).run()
      if (property.agent_id) {
        agent = await db.prepare(`SELECT * FROM agents WHERE id = ?`).bind(property.agent_id).first()
      }
      similar = (await db.prepare(
        `SELECT * FROM properties WHERE category = ? AND status = 'active' AND id != ? LIMIT 4`
      ).bind(property.category, property.id).all()).results || []

      const videosResult = await db.prepare(`SELECT * FROM property_videos WHERE property_id = ? OR property_listing_id = ? ORDER BY sort_order ASC`).bind(property.id, property.listing_id).all()
      videos = videosResult.results || []

      try {
        const roomsResult = await db.prepare(`SELECT * FROM property_rooms WHERE property_id = ? AND is_available = 1 ORDER BY sort_order ASC, id ASC`).bind(property.id).all()
        rooms = roomsResult.results || []
      } catch (_) {}

      const adsResult = await db.prepare(`SELECT * FROM ads WHERE is_active = 1 AND position = 'sidebar' ORDER BY created_at DESC LIMIT 2`).all()
      sidebarAds = adsResult.results || []
    }
  } catch (e) {}

  if (!property) return c.html(notFoundPage())
  return c.html(propertyDetailPage(property, similar, agent, videos, sidebarAds, rooms))
})

