app.get('/blog/:slug', async (c) => {
  const db = c.env.DB
  const slug = c.req.param('slug')
  let post: any = null
  let related: any[] = []
  let sidebarAds: any[] = []
  let inlineAds: any[] = []

  try {
    post = await db.prepare(`SELECT * FROM blog_posts WHERE slug = ? AND status = 'published'`).bind(slug).first()
    if (post) {
      await db.prepare(`UPDATE blog_posts SET views = views + 1 WHERE id = ?`).bind(post.id).run()
      related = (await db.prepare(`SELECT * FROM blog_posts WHERE id != ? AND status = 'published' ORDER BY created_at DESC LIMIT 3`).bind(post.id).all()).results || []
      const adsResult = await db.prepare(`SELECT * FROM ads WHERE is_active = 1 AND position = 'sidebar' ORDER BY created_at DESC LIMIT 2`).all()
      sidebarAds = adsResult.results || []
      const inlineAdsResult = await db.prepare(`SELECT * FROM ads WHERE is_active = 1 AND position = 'blog_inline' ORDER BY created_at DESC LIMIT 3`).all()
      inlineAds = inlineAdsResult.results || []
    }
  } catch (e) {}

  if (!post) return c.html(notFoundPage())
  return c.html(blogPostPage(post, related, sidebarAds, inlineAds))
})

