app.post('/admin/login', async (c) => {
  const body = await c.req.parseBody()
  const username = body.username as string
  const password = body.password as string
  const db = c.env.DB

  try {
    // Check super admin first
    const superAdminUser = username?.trim().toLowerCase()
    const isSuperAdmin = (superAdminUser === 'superadmin' || superAdminUser === 'superadmin@purecrest.ng') && password === 'PureCrest@SuperAdmin2026!'
    if (isSuperAdmin) {
      const token = btoa(`0:superadmin:${Date.now()}`)
      const isHttps = c.req.url.startsWith('https://') || c.req.header('x-forwarded-proto') === 'https'
      const attrs = isHttps ? 'Path=/; Max-Age=86400; SameSite=None; Secure' : 'Path=/; Max-Age=86400; SameSite=Lax'
      c.header('Set-Cookie', `admin_token=${token}; ${attrs}`, { append: true })
      c.header('Set-Cookie', `admin_role=superadmin; ${attrs}`, { append: true })
      return c.redirect('/admin/dashboard')
    }
    const admin = await db.prepare(
      `SELECT * FROM admin_accounts WHERE (username = ? OR email = ?) AND password = ? AND is_active = 1`
    ).bind(username, username, password).first() as any

    if (admin) {
      await db.prepare(`UPDATE admin_accounts SET last_login = CURRENT_TIMESTAMP WHERE id = ?`).bind(admin.id).run()
      const token = btoa(`${admin.id}:${admin.username}:${Date.now()}`)
      const role = admin.role || 'admin'
      const isHttps = c.req.url.startsWith('https://') || c.req.header('x-forwarded-proto') === 'https'
      const attrs = isHttps ? 'Path=/; Max-Age=86400; SameSite=None; Secure' : 'Path=/; Max-Age=86400; SameSite=Lax'
      c.header('Set-Cookie', `admin_token=${token}; ${attrs}`, { append: true })
      c.header('Set-Cookie', `admin_role=${role}; ${attrs}`, { append: true })
      return c.redirect('/admin/dashboard')
    }
  } catch (e) {}

  return c.html(adminLoginPage('Invalid username or password'))
})

app.get('/admin/logout', (c) => {
  const isHttps = c.req.url.startsWith('https://') || c.req.header('x-forwarded-proto') === 'https'
  const attrs = isHttps ? 'Path=/; Max-Age=0; SameSite=None; Secure' : 'Path=/; Max-Age=0; SameSite=Lax'
  c.header('Set-Cookie', `admin_token=; ${attrs}`, { append: true })
  c.header('Set-Cookie', `admin_role=; ${attrs}`, { append: true })
  return c.redirect('/admin/login')
})

app.get('/admin/dashboard', async (c) => {
  const db = c.env.DB
  let stats = { properties: 0, featured: 0, shortlets: 0, inquiries: 0, agents: 0, bookings: 0, blogs: 0, tours: 0, submissions: 0, propertyRequests: 0 }
  let recentProperties: any[] = []
  let recentInquiries: any[] = []

  try {
    const p = await db.prepare(`SELECT COUNT(*) as c FROM properties WHERE status='active'`).first() as any
    const f = await db.prepare(`SELECT COUNT(*) as c FROM properties WHERE is_featured=1`).first() as any
    const sl = await db.prepare(`SELECT COUNT(*) as c FROM properties WHERE category='short-let' AND status='active'`).first() as any
    const i = await db.prepare(`SELECT COUNT(*) as c FROM inquiries WHERE status='new'`).first() as any
    const ag = await db.prepare(`SELECT COUNT(*) as c FROM agents WHERE status='active'`).first() as any
    const b = await db.prepare(`SELECT COUNT(*) as c FROM bookings`).first() as any
    const bl = await db.prepare(`SELECT COUNT(*) as c FROM blog_posts WHERE status='published'`).first() as any
    const vt = await db.prepare(`SELECT COUNT(*) as c FROM virtual_tours WHERE status='pending'`).first() as any
    const sub = await db.prepare(`SELECT COUNT(*) as c FROM property_submissions WHERE status='pending'`).first() as any
    let preq = { c: 0 }
    try { preq = await db.prepare(`SELECT COUNT(*) as c FROM property_requests WHERE status='new'`).first() as any || { c: 0 } } catch(_) {}
    stats = { properties: p?.c||0, featured: f?.c||0, shortlets: sl?.c||0, inquiries: i?.c||0, agents: ag?.c||0, bookings: b?.c||0, blogs: bl?.c||0, tours: vt?.c||0, submissions: sub?.c||0, propertyRequests: preq?.c||0 }

    const pr = await db.prepare(`SELECT * FROM properties ORDER BY created_at DESC LIMIT 10`).all()
    recentProperties = (pr.results || []) as any[]

    const inq = await db.prepare(`SELECT * FROM inquiries ORDER BY created_at DESC LIMIT 10`).all()
    recentInquiries = (inq.results || []) as any[]
  } catch (e) {}

  return c.html(adminDashboardPage(stats, recentProperties, recentInquiries))
})

