// ============================================================
// VIDEO UPLOAD — supports direct file (<=10 MB) or external URL
// ============================================================
app.post('/api/upload-video', async (c) => {
  if (!hasAdminCookie(c)) return c.json({ success: false, error: 'Unauthorized' }, 401)
  const db = c.env.DB
  try {
    let body: any
    try { body = await c.req.parseBody() } catch(pe) { return c.json({ success: false, error: 'Could not parse request body' }) }
    const file = body['video'] as File | null
    const videoUrl = (body['video_url'] as string || '').trim()
    const propertyId = (body['property_id'] as string || '').trim()
    const listingId  = (body['listing_id']  as string || '').trim()
    const title = (body['title'] as string || 'Property Video').trim() || 'Property Video'
    const pid = (propertyId && !isNaN(parseInt(propertyId))) ? parseInt(propertyId) : null

    if (videoUrl) {
      let finalUrl = videoUrl
      let mimeType = 'video/external'
      const ytMatch = videoUrl.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/)
      if (ytMatch) {
        finalUrl = `https://www.youtube.com/embed/${ytMatch[1]}`
        mimeType = 'video/youtube'
      }
      const vimeoMatch = videoUrl.match(/vimeo\.com\/(?:video\/)?(\d+)/)
      if (vimeoMatch) {
        finalUrl = `https://player.vimeo.com/video/${vimeoMatch[1]}`
        mimeType = 'video/vimeo'
      }
      const result = await db.prepare(
        `INSERT INTO property_videos (property_id, property_listing_id, video_url, title, file_size, mime_type) VALUES (?,?,?,?,?,?)`
      ).bind(pid, listingId || '', finalUrl, title, 0, mimeType).run()
      try {
        await db.prepare(
          `INSERT INTO media_uploads (uploader_type, file_name, file_type, mime_type, file_url, file_size) VALUES ('admin',?,?,?,?,?)`
        ).bind(title, 'video', mimeType, finalUrl, 0).run()
      } catch(_) {}
      return c.json({ success: true, video_id: result.meta.last_row_id, url: finalUrl, type: mimeType.split('/')[1] })
    }

    if (!file || typeof file === 'string' || !file.size) {
      return c.json({ success: false, error: 'No video file or URL provided. Please select a video file or paste a YouTube/Vimeo URL.' })
    }
    if (!file.type.startsWith('video/')) {
      return c.json({ success: false, error: 'Invalid file type. Please upload a video file (MP4, MOV, WebM).' })
    }
    const maxSize = 10 * 1024 * 1024 // 10 MB
    if (file.size > maxSize) {
      return c.json({
        success: false,
        error: `Video file (${(file.size/1024/1024).toFixed(1)} MB) is too large. Max 10 MB for direct upload. For larger videos, upload to YouTube or Vimeo and paste the URL instead.`
      })
    }
    const buffer = await file.arrayBuffer()
    const bytes = new Uint8Array(buffer)
    const chunkSize = 8192
    let binary = ''
    for (let i = 0; i < bytes.byteLength; i += chunkSize) {
      binary += String.fromCharCode(...Array.from(bytes.slice(i, i + chunkSize)))
    }
    const dataUrl = `data:${file.type};base64,${btoa(binary)}`
    let mediaId: number | null = null
    try {
      const mr = await db.prepare(
        `INSERT INTO media_uploads (uploader_type, file_name, file_type, mime_type, file_url, file_size) VALUES ('admin',?,?,?,?,?)`
      ).bind(file.name || 'video-upload', 'video', file.type, dataUrl, file.size).run()
      mediaId = (mr.meta.last_row_id ?? null) as number | null
    } catch(_) {}
    const storedUrl = mediaId ? `/api/media/${mediaId}` : dataUrl
    const result = await db.prepare(
      `INSERT INTO property_videos (property_id, property_listing_id, video_url, title, file_size, mime_type) VALUES (?,?,?,?,?,?)`
    ).bind(pid, listingId || '', storedUrl, title, file.size, file.type).run()
    return c.json({ success: true, video_id: result.meta.last_row_id, url: storedUrl, type: 'upload' })
  } catch (e: any) {
    console.error('Video upload error:', e?.message || e)
    const msg = String(e?.message || 'Upload failed')
    if (msg.includes('too large') || msg.includes('D1_ERROR') || msg.includes('string too long')) {
      return c.json({ success: false, error: 'Video data too large for database. Please use a YouTube or Vimeo URL instead.' })
    }
    return c.json({ success: false, error: msg })
  }
})

