app.post('/admin/blog/save', async (c) => {
  const db = c.env.DB
  const body = await c.req.parseBody()
  const id = body.id as string
  const title = body.title as string
  const slug = (body.slug as string) || title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
  const excerpt = body.excerpt as string
  const content = body.content as string
  let coverImage = body.cover_image as string
  const author = body.author as string || 'PureCrest Team'
  const category = body.category as string || 'Market News'
  const status = body.status as string || 'published'

  // Handle uploaded cover image file
  const coverFile = body['cover_image_file'] as File
  if (coverFile && coverFile.size && coverFile.size <= 10 * 1024 * 1024) {
    const buffer = await coverFile.arrayBuffer()
    const bytes = new Uint8Array(buffer)
    const chunkSize = 8192
    let binary = ''
    for (let i = 0; i < bytes.byteLength; i += chunkSize) {
      binary += String.fromCharCode(...bytes.slice(i, i + chunkSize))
    }
    const b64 = btoa(binary)
    coverImage = `data:${coverFile.type};base64,${b64}`
    try {
      await db.prepare(`INSERT INTO media_uploads (uploader_type, file_name, file_type, mime_type, file_url, file_size) VALUES ('admin',?,?,?,?,?)`)
        .bind(coverFile.name || 'cover', 'image', coverFile.type, coverImage, coverFile.size).run()
    } catch(_) {}
  }

  try {
    if (id) {
      await db.prepare(`UPDATE blog_posts SET title=?,slug=?,excerpt=?,content=?,cover_image=?,author=?,category=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`)
        .bind(title, slug, excerpt, content, coverImage, author, category, status, id).run()
    } else {
      await db.prepare(`INSERT INTO blog_posts (title,slug,excerpt,content,cover_image,author,category,status) VALUES (?,?,?,?,?,?,?,?)`)
        .bind(title, slug, excerpt, content, coverImage, author, category, status).run()
    }
  } catch (e) { console.error(e) }
  return c.redirect('/admin/blog')
})

