// API: Add gallery item
app.post('/api/gallery/add', async (c) => {
  const db = c.env.DB
  try {
    await db.prepare(`CREATE TABLE IF NOT EXISTS gallery (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      title TEXT NOT NULL DEFAULT '',
      description TEXT DEFAULT '',
      media_type TEXT NOT NULL DEFAULT 'image',
      file_url TEXT NOT NULL,
      thumb_url TEXT DEFAULT '',
      source_type TEXT DEFAULT 'upload',
      youtube_id TEXT DEFAULT '',
      category TEXT DEFAULT 'general',
      sort_order INTEGER DEFAULT 0,
      is_active INTEGER DEFAULT 1,
      file_size INTEGER DEFAULT 0,
      mime_type TEXT DEFAULT '',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )`).run()
    const body = await c.req.parseBody()
    const mediaType = (body['media_type'] as string) || 'image'
    const title = (body['title'] as string) || ''
    const description = (body['description'] as string) || ''
    const category = (body['category'] as string) || 'general'
    const sortOrder = parseInt(body['sort_order'] as string || '0') || 0
    const urlInput = (body['file_url'] as string || '').trim()
    let fileUrl = ''
    let sourceType = 'url'
    let mimeType = ''
    let fileSize = 0
    let youtubeId = ''

    if (mediaType === 'video') {
      // Handle YouTube URL
      const ytMatch = urlInput.match(/(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/)
      if (ytMatch) {
        youtubeId = ytMatch[1]
        fileUrl = `https://www.youtube.com/embed/${youtubeId}`
        sourceType = 'youtube'
        mimeType = 'video/youtube'
      } else {
        fileUrl = urlInput
        sourceType = 'url'
        mimeType = 'video/external'
      }
      // Check for uploaded video file
      const videoFile = body['video_file'] as File
      if (videoFile && videoFile.size) {
        if (videoFile.size > 10 * 1024 * 1024) {
          return c.json({ success: false, error: 'Video file too large. Max 10MB.' })
        }
        const buffer = await videoFile.arrayBuffer()
        const bytes = new Uint8Array(buffer)
        const chunkSize = 8192
        let binary = ''
        for (let i = 0; i < bytes.byteLength; i += chunkSize) {
          binary += String.fromCharCode(...bytes.slice(i, i + chunkSize))
        }
        fileUrl = `data:${videoFile.type};base64,${btoa(binary)}`
        sourceType = 'upload'
        mimeType = videoFile.type
        fileSize = videoFile.size
        // Save video upload to media_uploads table
        try {
          await db.prepare(`INSERT INTO media_uploads (uploader_type, file_name, file_type, mime_type, file_url, file_size) VALUES ('admin',?,?,?,?,?)`)
            .bind(videoFile.name || 'gallery-video', 'video', videoFile.type, fileUrl, videoFile.size).run()
        } catch(_) {}
      }
    } else {
      // Image
      const imageFile = body['image_file'] as File
      if (imageFile && imageFile.size) {
        if (imageFile.size > 10 * 1024 * 1024) {
          return c.json({ success: false, error: 'Image too large. Max 10MB.' })
        }
        const buffer = await imageFile.arrayBuffer()
        const bytes = new Uint8Array(buffer)
        const chunkSize = 8192
        let binary = ''
        for (let i = 0; i < bytes.byteLength; i += chunkSize) {
          binary += String.fromCharCode(...bytes.slice(i, i + chunkSize))
        }
        fileUrl = `data:${imageFile.type};base64,${btoa(binary)}`
        sourceType = 'upload'
        mimeType = imageFile.type
        fileSize = imageFile.size
        // Also save to media_uploads
        try {
          await db.prepare(`INSERT INTO media_uploads (uploader_type, file_name, file_type, mime_type, file_url, file_size) VALUES ('admin',?,?,?,?,?)`)
            .bind(imageFile.name || 'gallery', 'image', imageFile.type, fileUrl, imageFile.size).run()
        } catch(_) {}
      } else if (urlInput) {
        fileUrl = urlInput
        sourceType = 'url'
      }
    }

    if (!fileUrl) return c.json({ success: false, error: 'No media provided' })

    const result = await db.prepare(`INSERT INTO gallery (title,description,media_type,file_url,source_type,youtube_id,category,sort_order,is_active,file_size,mime_type) VALUES (?,?,?,?,?,?,?,?,1,?,?)`)
      .bind(title, description, mediaType, fileUrl, sourceType, youtubeId, category, sortOrder, fileSize, mimeType).run()
    return c.json({ success: true, id: result.meta.last_row_id })
  } catch (e: any) {
    return c.json({ success: false, error: String(e?.message || 'Failed') })
  }
})

