app.post('/api/gallery/:id/update', async (c) => {
  const db = c.env.DB
  const id = c.req.param('id')
  try {
    const body = await c.req.parseBody()
    const title = (body['title'] as string) || ''
    const description = (body['description'] as string) || ''
    const category = (body['category'] as string) || 'general'
    const sortOrder = parseInt(body['sort_order'] as string || '0') || 0
    const isActive = body['is_active'] ? 1 : 0
    let fileUrl = (body['file_url'] as string || '').trim()

    // Handle new image upload for edit
    const imageFile = body['image_file'] as File
    if (imageFile && imageFile.size) {
      if (imageFile.size > 10 * 1024 * 1024) return c.json({ success: false, error: 'Image too large. Max 10MB.' })
      const buffer = await imageFile.arrayBuffer()
      const bytes = new Uint8Array(buffer)
      const chunkSize = 8192
      let binary = ''
      for (let i = 0; i < bytes.byteLength; i += chunkSize) {
        binary += String.fromCharCode(...bytes.slice(i, i + chunkSize))
      }
      fileUrl = `data:${imageFile.type};base64,${btoa(binary)}`
    }

    // Handle new video upload for edit
    const videoFile = body['video_file'] as File
    if (videoFile && videoFile.size) {
      if (videoFile.size > 10 * 1024 * 1024) return c.json({ success: false, error: 'Video too large. Max 10MB.' })
      const buffer = await videoFile.arrayBuffer()
      const bytes = new Uint8Array(buffer)
      const chunkSize = 8192
      let binary = ''
      for (let i = 0; i < bytes.byteLength; i += chunkSize) {
        binary += String.fromCharCode(...bytes.slice(i, i + chunkSize))
      }
      fileUrl = `data:${videoFile.type};base64,${btoa(binary)}`
    }

    // Handle YouTube URL in edit
    const urlInput = (body['new_url'] as string || '').trim()
    if (urlInput) {
      const ytMatch = urlInput.match(/(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/)
      if (ytMatch) {
        fileUrl = `https://www.youtube.com/embed/${ytMatch[1]}`
        await db.prepare(`UPDATE gallery SET youtube_id=?,source_type='youtube',mime_type='video/youtube' WHERE id=?`).bind(ytMatch[1], id).run()
      } else {
        fileUrl = urlInput
      }
    }

    if (fileUrl) {
      await db.prepare(`UPDATE gallery SET title=?,description=?,category=?,sort_order=?,is_active=?,file_url=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`)
        .bind(title, description, category, sortOrder, isActive, fileUrl, id).run()
    } else {
      await db.prepare(`UPDATE gallery SET title=?,description=?,category=?,sort_order=?,is_active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`)
        .bind(title, description, category, sortOrder, isActive, id).run()
    }
    return c.json({ success: true })
  } catch (e: any) {
    return c.json({ success: false, error: String(e?.message || 'Failed') })
  }
})

