app.post('/admin/cms/save', async (c) => {
  const db = c.env.DB
  let tab = 'homepage'
  try {
    const body = await c.req.parseBody({ all: true }) as Record<string, any>
    tab = String(body._tab || 'homepage').trim() || 'homepage'
    for (const [key, rawVal] of Object.entries(body)) {
      if (key.startsWith('_') || !/^[a-z0-9_]{2,64}$/.test(key)) continue
      let val = ''
      if (Array.isArray(rawVal)) {
        // Checkbox with hidden '0' fallback submits ['0', '1'] when checked
        val = String(rawVal[rawVal.length - 1] ?? '')
      } else if (typeof rawVal === 'string') {
        val = rawVal
      } else {
        continue
      }
      await db.prepare(
        `INSERT INTO site_settings (key, value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=?, updated_at=CURRENT_TIMESTAMP`
      ).bind(key, val, val).run()
    }
  } catch (e: any) {
    console.error('CMS save error:', e?.message || e)
  }
  return c.redirect(`/admin/cms?tab=${encodeURIComponent(tab)}&saved=1`)
})

// API: Upload any CMS / site setting image and save directly to media_uploads + site_settings
app.post('/api/upload-service-image', async (c) => {
  if (!hasAdminCookie(c)) return c.json({ success: false, error: 'Unauthorized — please log in to Admin' }, 401)
  const db = c.env.DB
  try {
    const body = await c.req.parseBody()
    const file = body['image'] as File | null
    const settingKey = (body['setting_key'] as string || '').trim()
    if (!settingKey || !/^[a-z0-9_]{2,64}$/.test(settingKey)) {
      return c.json({ success: false, error: 'Invalid setting key' })
    }
    if (!file || typeof file === 'string' || !file.size) {
      return c.json({ success: false, error: 'No image file received' })
    }
    if (!file.type.startsWith('image/')) {
      return c.json({ success: false, error: 'Invalid file type. Please upload an image.' })
    }
    if (file.size > 10 * 1024 * 1024) {
      return c.json({ success: false, error: `Image too large (${(file.size/1024/1024).toFixed(1)} MB). Max 10 MB.` })
    }
    const buffer = await file.arrayBuffer()
    const bytes = new Uint8Array(buffer)
    const chunkSize = 8192
    let binary = ''
    for (let i = 0; i < bytes.byteLength; i += chunkSize) {
      binary += String.fromCharCode(...Array.from(bytes.slice(i, i + chunkSize)))
    }
    const dataUrl = `data:${file.type};base64,${btoa(binary)}`
    let mediaId: number | null = null
    try {
      const mr = await db.prepare(
        `INSERT INTO media_uploads (uploader_type, file_name, file_type, mime_type, file_url, file_size) VALUES ('admin',?,?,?,?,?)`
      ).bind(file.name || settingKey, 'image', file.type, dataUrl, file.size).run()
      mediaId = (mr.meta.last_row_id ?? null) as number | null
    } catch (_) {}
    const mediaUrl = mediaId ? `/api/media/${mediaId}` : dataUrl
    await db.prepare(`INSERT INTO site_settings (key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=?, updated_at=CURRENT_TIMESTAMP`)
      .bind(settingKey, mediaUrl, mediaUrl).run()
    return c.json({ success: true, url: mediaUrl, key: settingKey, media_id: mediaId })
  } catch (e: any) {
    return c.json({ success: false, error: String(e?.message || 'Upload failed') })
  }
})

