app.post('/submit-property', async (c) => {
  const db = c.env.DB
  const body = await c.req.parseBody({ all: true })

  const facilities = (body.facilities_raw as string || '').split('\n').map((s: string) => s.trim()).filter(Boolean)
  let images: string[] = []

  // Handle uploaded image files
  const imgFiles = Array.isArray(body['image_files']) ? body['image_files'] as File[] : (body['image_files'] ? [body['image_files'] as File] : [])
  for (const file of imgFiles) {
    if (file && file.size && file.size <= 10 * 1024 * 1024) {
      const buffer = await file.arrayBuffer()
      const bytes = new Uint8Array(buffer)
      const chunkSize = 8192
      let binary = ''
      for (let i = 0; i < bytes.byteLength; i += chunkSize) {
        binary += String.fromCharCode(...bytes.slice(i, i + chunkSize))
      }
      const b64 = btoa(binary)
      images.push(`data:${file.type};base64,${b64}`)
    }
  }

  // Also accept pasted image URLs
  const urlImages = (body.images_raw as string || '').split('\n').map((s: string) => s.trim()).filter(Boolean)
  images = [...images, ...urlImages.filter((u: string) => u.startsWith('http'))]

  try {
    await db.prepare(
      `INSERT INTO property_submissions (submitter_name, submitter_phone, submitter_email, title, description, property_type, category, price, price_period, bedrooms, bathrooms, toilets, size_sqm, location, address, area, facilities, images, amenities, house_rules, additional_notes, year_built, status)
       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
    ).bind(
      body.submitter_name, body.submitter_phone, body.submitter_email||'',
      body.title, body.description||'',
      body.property_type, body.category,
      parseFloat(body.price as string)||0, body.price_period,
      parseInt(body.bedrooms as string)||0, parseInt(body.bathrooms as string)||0,
      parseInt(body.toilets as string)||0, parseFloat(body.size_sqm as string)||0,
      body.location, body.address||'', body.area,
      JSON.stringify(facilities), JSON.stringify(images),
      '[]', '[]',
      body.additional_notes||'',
      parseInt(body.year_built as string)||null,
      'pending'
    ).run()
    return c.html(submitPropertySuccessPage())
  } catch (e: any) {
    console.error('Submission error:', e)
    const settings = await getSiteSettings(db)
    return c.html(submitPropertyPage(settings, 'An error occurred. Please try again.'))
  }
})

