app.post('/admin/users/save', async (c) => {
  const db = c.env.DB
  const body = await c.req.parseBody()
  const id = body.id as string
  const username = body.username as string
  const email = (body.email as string) || ''
  const password = body.password as string
  const role = (body.role as string) || 'admin'
  const is_active = body.is_active ? 1 : 0

  try {
    if (id) {
      if (password) {
        await db.prepare(`UPDATE admin_accounts SET username=?, email=?, password=?, role=?, is_active=? WHERE id=?`)
          .bind(username, email, password, role, is_active, id).run()
      } else {
        await db.prepare(`UPDATE admin_accounts SET username=?, email=?, role=?, is_active=? WHERE id=?`)
          .bind(username, email, role, is_active, id).run()
      }
    } else {
      await db.prepare(`INSERT INTO admin_accounts (username, email, password, role, is_active) VALUES (?,?,?,?,?)`)
        .bind(username, email, password, role, 1).run()
    }
  } catch (e: any) { console.error('User save error:', e) }
  return c.redirect('/admin/users')
})

