  const lagosAreas = ['Victoria Island', 'Lekki', 'Ikoyi', 'Ajah', 'Yaba', 'Surulere', 'Ikeja', 'Lagos Island', 'Apapa', 'Maryland', 'Gbagada', 'Magodo', 'Lekki Phase 1', 'Sangotedo']
