      <h2 style="font-family:'DM Serif Display',serif; font-size:clamp(1.5rem,3vw,2.4rem); color:#fff; margin:0 0 16px; font-weight:400; max-width:640px; line-height:1.2; margin-left:auto; margin-right:auto;">${escHtml(settings.hosp_cta_title || 'Let Purecrest Manage Your Shortlet or Hotel — We Deliver Results with Integrity')}</h2>
