function adminBlogFormPage(post: any): string {
  const isEdit = !!post
  const content = `
  <div class="max-w-4xl">
    <div class="mb-4"><a href="/admin/blog" class="text-sm text-gray-500 hover:text-gray-700 flex items-center gap-1"><i class="fas fa-arrow-left"></i>Back to Blog</a></div>
    <form method="POST" action="/admin/blog/save" enctype="multipart/form-data" class="space-y-5">
      ${isEdit ? `<input type="hidden" name="id" value="${post.id}" />` : ''}
      <div class="bg-white rounded-xl shadow-sm p-5 space-y-4">
        <h2 class="font-bold text-gray-800">Post Details</h2>
        <div><label class="block text-sm font-medium text-gray-700 mb-1">Title *</label><input type="text" name="title" value="${post?.title||''}" required class="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none" style="border-color:#e2e8f0;" /></div>
        <div><label class="block text-sm font-medium text-gray-700 mb-1">URL Slug (auto-generated if empty)</label><input type="text" name="slug" value="${post?.slug||''}" placeholder="e.g. buying-a-home-in-abuja" class="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none font-mono" style="border-color:#e2e8f0;" /></div>
        <div><label class="block text-sm font-medium text-gray-700 mb-1">Excerpt / Summary</label><textarea name="excerpt" rows="2" class="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none" style="border-color:#e2e8f0;">${post?.excerpt||''}</textarea></div>
        
        <!-- Cover Image with direct upload -->
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-2">Cover / Featured Image</label>
          ${post?.cover_image ? `
          <div class="mb-3 relative group" id="coverPreviewWrap">
            <img src="${post.cover_image}" id="coverPreview" class="w-full rounded-xl object-cover" style="max-height:200px;" />
            <button type="button" onclick="clearCoverImage()" class="absolute top-2 right-2 bg-red-500 text-white rounded-full w-7 h-7 flex items-center justify-center text-xs hover:bg-red-600 opacity-0 group-hover:opacity-100 transition-opacity">
              <i class="fas fa-times"></i>
            </button>
          </div>` : `<div id="coverPreviewWrap" class="hidden mb-3 relative group">
            <img id="coverPreview" class="w-full rounded-xl object-cover" style="max-height:200px;" />
            <button type="button" onclick="clearCoverImage()" class="absolute top-2 right-2 bg-red-500 text-white rounded-full w-7 h-7 flex items-center justify-center text-xs hover:bg-red-600">
              <i class="fas fa-times"></i>
            </button>
          </div>`}
          <div class="flex gap-3 items-start">
            <div class="flex-1">
              <div class="border-2 border-dashed rounded-xl p-4 text-center cursor-pointer hover:border-emerald-400 transition-colors" style="border-color:#e2e8f0;" onclick="document.getElementById('coverFileInput').click()">
                <i class="fas fa-cloud-upload-alt text-2xl text-gray-400 mb-1 block"></i>
                <p class="text-xs text-gray-500">Click to upload cover image</p>
                <p class="text-xs text-gray-400">JPG, PNG, WebP · Max 10 MB</p>
              </div>
              <input type="file" id="coverFileInput" name="cover_image_file" accept="image/*" class="hidden" />
            </div>
            <div class="flex-1">
              <input type="text" name="cover_image" id="coverImageUrl" value="${post?.cover_image&&!post.cover_image.startsWith('data:') ? post.cover_image : ''}" placeholder="Or paste image URL..." class="w-full px-3 py-2.5 border rounded-lg text-sm focus:outline-none" style="border-color:#e2e8f0;" />
              <p class="text-xs text-gray-400 mt-1">Enter a URL or upload a file above</p>
            </div>
          </div>
        </div>

        <div class="grid grid-cols-2 gap-4">
          <div>
            <label class="block text-sm font-medium text-gray-700 mb-1">Category</label>
            <select name="category" class="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none bg-white" style="border-color:#e2e8f0;">
              ${['Market News','Buying Guide','Renting Tips','Investment','Lifestyle','Abuja Living'].map((c: string) => `<option value="${c}" ${post?.category===c?'selected':''}>${c}</option>`).join('')}
            </select>
          </div>
          <div>
            <label class="block text-sm font-medium text-gray-700 mb-1">Author</label>
            <input type="text" name="author" value="${post?.author||'PureCrest Team'}" class="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none" style="border-color:#e2e8f0;" />
          </div>
        </div>
        <div>
          <label class="block text-sm font-medium text-gray-700 mb-1">Status</label>
          <select name="status" class="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none bg-white" style="border-color:#e2e8f0;">
            <option value="published" ${post?.status==='published'?'selected':''}>Published</option>
            <option value="draft" ${post?.status==='draft'?'selected':''}>Draft</option>
          </select>
        </div>
      </div>

      <!-- Rich Text Editor -->
      <div class="bg-white rounded-xl shadow-sm p-5">
        <h2 class="font-bold text-gray-800 mb-3">Content</h2>
        <!-- Toolbar -->
        <div class="flex flex-wrap gap-1 p-2 border border-b-0 rounded-t-xl bg-gray-50" id="editorToolbar" style="border-color:#e2e8f0;">
          <button type="button" onclick="execCmd('bold')" title="Bold" class="toolbar-btn"><i class="fas fa-bold"></i></button>
          <button type="button" onclick="execCmd('italic')" title="Italic" class="toolbar-btn"><i class="fas fa-italic"></i></button>
          <button type="button" onclick="execCmd('underline')" title="Underline" class="toolbar-btn"><i class="fas fa-underline"></i></button>
          <div class="w-px bg-gray-300 mx-1"></div>
          <button type="button" onclick="execFormatBlock('h2')" title="Heading 2" class="toolbar-btn">H2</button>
          <button type="button" onclick="execFormatBlock('h3')" title="Heading 3" class="toolbar-btn">H3</button>
          <button type="button" onclick="execFormatBlock('p')" title="Paragraph" class="toolbar-btn">P</button>
          <div class="w-px bg-gray-300 mx-1"></div>
          <button type="button" onclick="execCmd('insertUnorderedList')" title="Bullet List" class="toolbar-btn"><i class="fas fa-list-ul"></i></button>
          <button type="button" onclick="execCmd('insertOrderedList')" title="Numbered List" class="toolbar-btn"><i class="fas fa-list-ol"></i></button>
          <div class="w-px bg-gray-300 mx-1"></div>
          <button type="button" onclick="execFormatBlock('blockquote')" title="Quote" class="toolbar-btn"><i class="fas fa-quote-left"></i></button>
          <div class="w-px bg-gray-300 mx-1"></div>
          <button type="button" onclick="insertLink()" title="Insert Link" class="toolbar-btn"><i class="fas fa-link"></i></button>
          <button type="button" onclick="insertImageInEditor()" title="Insert Image" class="toolbar-btn"><i class="fas fa-image"></i></button>
          <div class="w-px bg-gray-300 mx-1"></div>
          <button type="button" onclick="execCmd('removeFormat')" title="Clear Formatting" class="toolbar-btn text-red-400"><i class="fas fa-eraser"></i></button>
        </div>
        <div id="richEditor" contenteditable="true" class="w-full min-h-[350px] px-4 py-3 border rounded-b-xl text-sm focus:outline-none blog-content" style="border-color:#e2e8f0; line-height:1.8;"></div>
        <textarea name="content" id="contentTextarea" class="hidden">${(post?.content||'').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/&lt;/g,'<').replace(/&gt;/g,'>')}</textarea>
        <p class="text-xs text-gray-400 mt-2">Use the toolbar for formatting, or switch to <button type="button" onclick="toggleEditorMode()" class="underline text-blue-500">HTML mode</button></p>
        <div id="htmlModeWrap" class="hidden mt-2">
          <textarea id="htmlEditor" rows="16" class="w-full px-3 py-2 border rounded-lg text-sm focus:outline-none font-mono" style="border-color:#e2e8f0;"></textarea>
        </div>
      </div>

      <div class="flex gap-4">
        <button type="submit" class="btn-gold text-white px-8 py-3 rounded-xl font-semibold">${isEdit ? 'Update Post' : 'Publish Post'}</button>
        <a href="/admin/blog" class="bg-gray-200 text-gray-700 px-6 py-3 rounded-xl font-medium hover:bg-gray-300">Cancel</a>
      </div>
    </form>
  </div>
  <style>
    .toolbar-btn { padding: 5px 8px; border-radius: 4px; font-size: 13px; font-weight: 600; color: #374151; background: white; border: 1px solid #e5e7eb; cursor: pointer; min-width: 28px; transition: all 0.15s; }
    .toolbar-btn:hover { background: #f3f4f6; border-color: #d1d5db; }
    #richEditor:focus { border-color: #C9A84C !important; }
    #richEditor h2 { font-family: 'DM Serif Display', serif; font-size: 1.4rem; font-weight: 700; margin: 1.2rem 0 0.5rem; color: #1e293b; }
    #richEditor h3 { font-family: 'DM Serif Display', serif; font-size: 1.1rem; font-weight: 700; margin: 1rem 0 0.4rem; color: #334155; }
    #richEditor p { margin-bottom: 0.75rem; color: #475569; }
    #richEditor blockquote { border-left: 4px solid #C9A84C; padding-left: 1rem; margin: 1rem 0; font-style: italic; color: #64748b; }
    #richEditor ul { list-style: disc; padding-left: 1.5rem; margin-bottom: 0.75rem; }
    #richEditor ol { list-style: decimal; padding-left: 1.5rem; margin-bottom: 0.75rem; }
  </style>
  <script>
    // Rich editor init
    const richEditor = document.getElementById('richEditor');
    const contentTA = document.getElementById('contentTextarea');
    const htmlEditor = document.getElementById('htmlEditor');
    let isHtmlMode = false;

    // Load initial content
    richEditor.innerHTML = contentTA.value;

    function execCmd(cmd) { document.execCommand(cmd, false, null); richEditor.focus(); }
    function execFormatBlock(tag) { document.execCommand('formatBlock', false, '<'+tag+'>'); richEditor.focus(); }
    function insertLink() {
      const url = prompt('Enter URL:');
      if (url) { const text = window.getSelection()?.toString() || url; document.execCommand('insertHTML', false, '<a href="'+url+'" target="_blank">'+text+'</a>'); }
      richEditor.focus();
    }
    function insertImageInEditor() {
      const url = prompt('Enter image URL (or leave empty to upload):');
      if (url) { document.execCommand('insertHTML', false, '<img src="'+url+'" style="max-width:100%;border-radius:8px;margin:8px 0;" />'); }
      else {
        const inp = document.createElement('input'); inp.type='file'; inp.accept='image/*';
        inp.onchange = async (e) => {
          const file = e.target.files[0]; if(!file) return;
          const fd = new FormData(); fd.append('image', file);
          const res = await fetch('/api/upload-image', {method:'POST', body:fd});
          const data = await res.json();
          if(data.success) { richEditor.focus(); document.execCommand('insertHTML', false, '<img src="'+data.url+'" style="max-width:100%;border-radius:8px;margin:8px 0;" />'); }
          else alert('Upload failed: '+(data.error||''));
        }; inp.click();
      }
      richEditor.focus();
    }
    function toggleEditorMode() {
      isHtmlMode = !isHtmlMode;
      if (isHtmlMode) {
        htmlEditor.value = richEditor.innerHTML;
        document.getElementById('richEditor').classList.add('hidden');
        document.getElementById('htmlModeWrap').classList.remove('hidden');
        document.getElementById('editorToolbar').style.opacity = '0.4';
      } else {
        richEditor.innerHTML = htmlEditor.value;
        document.getElementById('richEditor').classList.remove('hidden');
        document.getElementById('htmlModeWrap').classList.add('hidden');
        document.getElementById('editorToolbar').style.opacity = '1';
      }
    }
    // Sync content to textarea before submit
    document.querySelector('form').addEventListener('submit', (e) => {
      if (isHtmlMode) { richEditor.innerHTML = htmlEditor.value; }
      contentTA.value = richEditor.innerHTML;
    });

    // Cover image upload preview
    const coverFileInput = document.getElementById('coverFileInput');
    const coverPreview = document.getElementById('coverPreview');
    const coverPreviewWrap = document.getElementById('coverPreviewWrap');
    const coverImageUrl = document.getElementById('coverImageUrl');
    if (coverFileInput) {
      coverFileInput.addEventListener('change', async (e) => {
        const file = e.target.files[0]; if(!file) return;
        const fd = new FormData(); fd.append('image', file);
        try {
          const res = await fetch('/api/upload-image', {method:'POST', body:fd});
          const data = await res.json();
          if(data.success) {
            coverPreview.src = data.url;
            coverImageUrl.value = data.url;
            coverPreviewWrap.classList.remove('hidden');
          } else { alert('Upload failed: '+(data.error||'')); }
        } catch(err) { alert('Upload error'); }
        e.target.value = '';
      });
    }
    // URL input preview
    if (coverImageUrl) {
      coverImageUrl.addEventListener('blur', () => {
        const url = coverImageUrl.value.trim();
        if (url && url.startsWith('http')) {
          coverPreview.src = url;
          coverPreviewWrap.classList.remove('hidden');
        }
      });
    }
    function clearCoverImage() {
      coverPreview.src = '';
      coverImageUrl.value = '';
      coverPreviewWrap.classList.add('hidden');
      if(coverFileInput) coverFileInput.value = '';
    }
  </script>`
  return adminLayout(isEdit ? 'Edit Post' : 'New Post', content, 'blog')
}

